	TransferOrderLineEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTransferOrderLineEvent
     */
    @EventHandler
    public void handle( CreateTransferOrderLineEvent event) {
        entityManager.persist(new TransferOrderLine(event.getTransferOrderLineId(), event.getLineNumber(), event.getQuantity(), event.getTransferOrder(), event.getSku(), event.getLot(), event.getSerialNumbers(), event.getFromLocation(), event.getToLocation(), event.getUnitOfMeasure(), event.getStockStatus()));
    }

    /*
     * @param	event UpdateTransferOrderLineEvent
     */
    @EventHandler
    public TransferOrderLine handle( UpdateTransferOrderLineEvent event) {
    	entityManager.merge(new TransferOrderLine(event.getTransferOrderLineId(), event.getLineNumber(), event.getQuantity(), event.getTransferOrder(), event.getSku(), event.getLot(), event.getSerialNumbers(), event.getFromLocation(), event.getToLocation(), event.getUnitOfMeasure(), event.getStockStatus()));
    }
    
    /*
     * @param	event DeleteTransferOrderLineEvent
     */
    @EventHandler
    public void on( DeleteTransferOrderLineEvent event) {
    	TransferOrderLine entity = new TransferOrderLine();
   
    	// ------------------------------------------
    	// apply the TransferOrderLineId
    	// ------------------------------------------
    	entity.setTransferOrderLineId( event.getTransferOrderLineId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
